-- turn_admin_cost_rows(timestamp with time zone,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.turn_admin_cost_rows(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(call_key text, user_id uuid, model_used text, total_credits integer, total_cost_usd text, cached_tokens integer, input_tokens integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF p_from IS NULL OR p_to IS NULL OR p_from >= p_to OR p_to - p_from > interval '92 days' THEN
  RAISE EXCEPTION 'TURN_REPORT_WINDOW_INVALID' USING ERRCODE='22023';
 END IF;
 RETURN QUERY
 -- The credit-carrying call is chosen among the turn's whole set of spent calls BEFORE the time window is applied, so the same call
 -- carries the credits whatever window is asked for (a turn spanning a day or month boundary is never counted in two places).
 WITH ranked AS (
  SELECT k.*, row_number() OVER (PARTITION BY k.turn_id ORDER BY k.seq) first_rank
  FROM turn_calls k WHERE k.call_kind IN ('model','decision') AND k.status IN ('ok','unusable')
   AND k.turn_id IN (SELECT w.turn_id FROM turn_calls w WHERE w.dispatched_at>=p_from AND w.dispatched_at<p_to)
 )
 SELECT k.turn_id::text || ':' || k.seq::text,
  k.actor_id,
  -- A decision call is attributed to the model its receipt names, never to the turn's main model.
  (CASE WHEN k.call_kind='decision' THEN coalesce(nullif(k.usage->>'model',''), 'decision (model not recorded)')
    ELSE coalesce(t.policy->'models'->>(k.model_id::text), t.policy->>'model', 'unknown') END)::text,
  (CASE WHEN k.first_rank=1 THEN coalesce(t.charged_credits,0) ELSE 0 END)::integer,
  (CASE WHEN k.status='ok' THEN turn_call_spent_usd(k.call_kind,k.nominal_usd,k.actual_usd) ELSE coalesce(k.actual_usd,0) END)::text,
  NULL::integer, NULL::integer, k.dispatched_at
 FROM ranked k JOIN turns t ON t.actor_id=k.actor_id AND t.id=k.turn_id
 WHERE k.dispatched_at>=p_from AND k.dispatched_at<p_to;
END $function$;
